import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.Connection;
import java.util.HashMap;
import java.net.MalformedURLException;
import java.net.URI;
import java.net.URISyntaxException;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void newUrlBuilder constructionTest() {
        assertNotNull(new UrlBuilder(null));
    }

    @Test
    public void build_urlWithNoParameters_test() throws MalformedURLException, URISyntaxException {
        Connection connection = mock(Connection.class);
        when(connection.getUri()).thenReturn(URI.create("https://example.com"));
        UrlBuilder urlBuilder = new UrlBuilder(connection);
        URL result = urlBuilder.build();
        assertEquals(new URI("https://example.com"), result.toURI());
    }

    @Test
    public void build_urlWithQueryParameters_test() throws MalformedURLException, URISyntaxException {
        Connection connection = mock(Connection.class);
        when(connection.getUri()).thenReturn(URI.create("https://example.com?a=1&b=2"));
        UrlBuilder urlBuilder = new UrlBuilder(connection);
        URL result = urlBuilder.build();
        assertEquals(new URI("https://example.com?1=a&2=b"), result.toURI());
    }

    @Test
    public void appendKeyVal_addsKeyValuePairs_test() throws UnsupportedEncodingException {
        Connection connection = mock(Connection.class);
        when(connection.getUri()).thenReturn(URI.create("https://example.com"));
        UrlBuilder urlBuilder = new UrlBuilder(connection);
        HashMap<String, String> keyVal = new HashMap<>();
        keyVal.put("a", "1");
        keyVal.put("b", "2");
        urlBuilder.appendKeyVal(Connection.KeyVal.of(keyVal));
        assertEquals(new URI("https://example.com?a=1&b=2"), urlBuilder.build().toURI());
    }

    @Test
    public void appendKeyVal_withoutKeyValuePairs_doesNotModifyUrl_test() throws UnsupportedEncodingException {
        Connection connection = mock(Connection.class);
        when(connection.getUri()).thenReturn(URI.create("https://example.com"));
        UrlBuilder urlBuilder = new UrlBuilder(connection);
        urlBuilder.appendKeyVal(null);
        assertEquals(new URI("https://example.com"), urlBuilder.build().toURI());
    }
}
